{
  "AGENTS.md": "# Notes for agents

Read [CONTRIBUTING.md](CONTRIBUTING.md) before you change this repository. In particular:

- **Commits.** Use Conventional Commits, as in [Commit messages](CONTRIBUTING.md#commit-messages). The `commitlint` job in [`ci.yml`](.github/workflows/ci.yml) checks every commit of a pull request with [`commitlint.config.js`](commitlint.config.js). `git commit --no-verify` does not skip it.
- **Checks.** Run `npm run check` before you push. CI runs the same command.
- **Docs.** Update the documentation when you change behavior. Follow the [documentation style](CONTRIBUTING.md#documentation-style).
",
  "src/thread.ts": "import {
	BACKGROUND_CONTEXT,
	type Context,
} from "@earendil-works/chord/context";
import type { Api, Model } from "@earendil-works/pi-ai";
import type { Models } from "@earendil-works/pi-ai/models";
import {
	type AgentChange,
	AssistantEntry,
	type CommitResult,
	type Conversation,
	createRegistry,
	type EntryId,
	type EntryRecord,
	type Extension,
	Harness,
	MemoryStorage,
	type Storage,
	type StorageWrite,
	type Submission,
	type ToolRegistration,
	ToolResultEntry,
} from "@earendil-works/pi-durable";
import { NodeExecutionEnv } from "@earendil-works/pi-durable/env/node";
import { CodingTools } from "@earendil-works/pi-durable/tools";

import { GitStorage } from "./storage/git-storage.ts";
import { git } from "./storage/git.ts";
import { GitSync, isTurnBoundary, liveRef } from "./storage/sync.ts";
import { type SnapshotLimits, worktreeRef } from "./storage/worktree.ts";
import { planTools, type ToolSelection } from "./tool-filter.ts";
import type { Log } from "./types.ts";
import { getErrorMessage } from "./utils.ts";
import { RESTORE_ENTRY_KIND, WorktreeContinuity } from "./worktree.ts";

const context: Context = BACKGROUND_CONTEXT;

const POSTED_KIND = "pi-action.posted";
const COMMENT_KIND = "pi-action.comment";
const KEY_FIELD = "key";
const URL_FIELD = "url";

export const threadRef = (issueNumber: number): string =>
	`refs/pi/threads/${issueNumber}`;

export interface ThreadOptions {
	cwd: string;
	/** The issue or PR; undefined for a one-off prompt, which is kept in memory only. */
	issueNumber?: number | undefined;
	models: Models;
	model: Model<Api>;
	log: Log;
	remote?: string | undefined;
	/** pi-durable extensions from the `extensions` input, installed after the coding tools. */
	extensions?: readonly Extension[];
	/** The `exclude_tools` and `model_tools_hidden` inputs; none when undefined. */
	tools?: ToolSelection | undefined;
	/** Variables the tools' shell gets on top of the process environment (see `toolEnv()`). */
	toolEnv?: Readonly<Record<string, string>> | undefined;
	/** Save and restore the working tree with the thread (stored threads only), with these limits; undefined: don't. */
	worktree?: SnapshotLimits | undefined;
	/** Called with the entries of each stored commit, in order (see activity.ts); must not throw. */
	onEntries?: ((entries: readonly EntryRecord[]) => void) | undefined;
}

/** The entries among `writes`. */
function entriesOf(writes: readonly StorageWrite[]): EntryRecord[] {
	return writes.flatMap((write) =>
		write.type === "entry" ? [write.value] : [],
	);
}

/** A one-off conversation's storage, which reports the entries it stores as GitStorage's `onCommit` does. */
class ObservedMemoryStorage extends MemoryStorage {
	private readonly onEntries: (entries: readonly EntryRecord[]) => void;

	constructor(onEntries: (entries: readonly EntryRecord[]) => void) {
		super();
		this.onEntries = onEntries;
	}

	override async commit(
		...args: Parameters<MemoryStorage["commit"]>
	): Promise<CommitResult> {
		const result = await super.commit(...args);
		this.onEntries(
			args[0].slice(0, result.stored).flatMap((writes) => entriesOf(writes)),
		);
		return result;
	}
}

/** What `Thread.answerText()` reports about a run's answer. */
export interface RunAnswer {
	text: string;
	toolCalls: boolean;
	/** The assistant message's stop reason; `length` when it hit the output token limit (max_tokens). */
	stopReason: string | undefined;
	/** Whether the run executed tools before this answer. */
	usedTools: boolean;
}

export interface ThreadInput {
	/** Stable per GitHub item, e.g. `comment-123`: resubmitting it returns the same submission. */
	key: string;
	content: string;
	data: Record<string, string>;
	/** Place the input as this entry instead of a comment (an answer to a question: `ui.answer`). */
	entry?: { kind: string; data: Record<string, string | boolean> } | undefined;
}

interface Persistence {
	ref: string;
	storage: GitStorage;
	saver: ThreadSaver;
	worktree: WorktreeContinuity | undefined;
	startedAt: Date | undefined;
	isNew: boolean;
}

/** The local tip of `ref`, undefined when it doesn't exist. */
async function localTip(cwd: string, ref: string): Promise<string | undefined> {
	const out = await git(cwd, ["rev-parse", "-q", "--verify", ref]).catch(
		() => "",
	);
	return out.trim() || undefined;
}

/** Pushes the thread, and the working-tree snapshots with it. */
class ThreadSaver {
	private readonly cwd: string;
	private readonly sync: GitSync;
	private readonly worktree: WorktreeContinuity | undefined;
	/** Set once the storage is open. */
	storage: GitStorage | undefined;

	constructor(
		cwd: string,
		sync: GitSync,
		worktree: WorktreeContinuity | undefined,
	) {
		this.cwd = cwd;
		this.sync = sync;
		this.worktree = worktree;
	}

	/** Push now (`flush`) or soon (`schedule`), saving the working tree first when `save`. */
	async push(how: "schedule" | "flush", save: boolean): Promise<void> {
		const tip = () => this.storage?.tip;
		if (this.worktree !== undefined && save) {
			await this.worktree.checkpoint();
		}
		const companion =
			this.worktree === undefined
				? undefined
				: await localTip(this.cwd, this.worktree.ref);
		const current = tip();
		if (how === "flush") {
			await this.sync.flush(current, companion);
		} else if (current !== undefined) {
			await this.sync.schedule(current, companion);
		}
	}
}

async function openPersistence(
	options: ThreadOptions,
	issueNumber: number,
): Promise<Persistence> {
	const { cwd, log } = options;
	const ref = threadRef(issueNumber);
	// The run works on local refs outside refs/pi/, where a fetch the agent runs can't move them (#46).
	const local = liveRef(ref);
	const worktree =
		options.worktree === undefined
			? undefined
			: new WorktreeContinuity({
					cwd,
					ref: liveRef(worktreeRef(issueNumber)),
					name: worktreeRef(issueNumber),
					limits: options.worktree,
					log,
					remote: options.remote,
				});
	const sync = new GitSync({
		repo: cwd,
		ref,
		localRef: local,
		companionRef: worktree === undefined ? undefined : worktreeRef(issueNumber),
		localCompanionRef: worktree?.ref,
		log: log.debug ?? log.info,
		remote: options.remote,
	});
	const remoteTip = await sync.fetch();
	const saver = new ThreadSaver(cwd, sync, worktree);
	const storage = await GitStorage.open({
		repo: cwd,
		ref: local,
		author: {
			name: "pi-action",
			email: "pi-action@users.noreply.github.com",
		},
		onCommit: ({ batches }) => {
			options.onEntries?.(batches.flatMap((batch) => entriesOf(batch.writes)));
			if (isTurnBoundary(batches)) {
				saver.push("schedule", true).catch((error: unknown) => {
					log.warning(getErrorMessage(error));
				});
			}
		},
	});
	saver.storage = storage;
	return {
		ref,
		storage,
		saver,
		worktree,
		isNew: remoteTip === undefined,
		startedAt: remoteTip ? await rootCommitTime(cwd, local) : undefined,
	};
}

/**
 * One GitHub issue or PR as a durable pi conversation, stored in git on refs/pi/threads/<n> and pushed to the
 * remote at every turn boundary. Without an issue number, the conversation lives in memory for this run only.
 */
export class Thread {
	private closed = false;
	private readonly harness: Harness;
	private readonly root: Conversation;
	private readonly persistence: Persistence | undefined;
	/** The names of the tools the model is offered. */
	readonly modelTools: readonly string[];

	private constructor(
		harness: Harness,
		root: Conversation,
		persistence: Persistence | undefined,
		modelTools: readonly string[],
	) {
		this.harness = harness;
		this.root = root;
		this.persistence = persistence;
		this.modelTools = modelTools;
	}

	static async open(options: ThreadOptions): Promise<Thread> {
		const { cwd } = options;
		const persistence =
			options.issueNumber === undefined
				? undefined
				: await openPersistence(options, options.issueNumber);
		const { onEntries } = options;
		const storage: Storage =
			persistence?.storage ??
			(onEntries === undefined
				? new MemoryStorage()
				: new ObservedMemoryStorage(onEntries));
		const registry = createRegistry();
		registry.install(CodingTools);
		for (const extension of options.extensions ?? []) {
			registry.install(extension);
		}
		const harness = await Harness.open(
			storage,
			{
				models: options.models,
				registry,
				env: ({ cwd: dir }) =>
					new NodeExecutionEnv({
						cwd: dir ?? cwd,
						shellEnv: { ...options.toolEnv },
					}),
				settings: { retry: { maxRetries: 2 } },
			},
			context,
		);
		const agent = {
			model: { provider: options.model.provider, modelId: options.model.id },
			cwd,
		};
		let modelTools: string[];
		let root: Conversation;
		try {
			root = await harness.root(context, { agent });
			modelTools = await configureAgent(root, agent, options);
		} catch (error) {
			await harness.close(context);
			throw error;
		}
		await restoreWorktree(persistence?.worktree, harness, root);
		harness.resume(); // finish whatever a previous, interrupted run left
		return new Thread(harness, root, persistence, modelTools);
	}

	/** The commit the thread's ref points at, undefined before its first commit or when it is not stored. */
	get tip(): string | undefined {
		return this.persistence?.storage.tip;
	}

	/** The thread's ref, when it is stored in git. */
	get ref(): string | undefined {
		return this.persistence?.ref;
	}

	/** A thread nothing was stored for yet (always, in memory). */
	get isNew(): boolean {
		return this.persistence?.isNew ?? true;
	}

	/** When the thread's first commit was made; undefined for a new thread. */
	get startedAt(): Date | undefined {
		return this.persistence?.startedAt;
	}

	/** Comments arriving while a run works join it (steer); otherwise they start one. */
	async submit(input: ThreadInput): Promise<Submission> {
		return this.root.submit(
			{
				type: "input",
				content: input.content,
				requestId: input.key,
				whenBusy: "steer",
				entry: input.entry ?? {
					kind: COMMENT_KIND,
					data: { key: input.key, ...input.data },
				},
			},
			context,
		);
	}

	/**
	 * A run's answer: its text, whether it called tools (a run that ended on a `terminate` round), and why the
	 * model stopped (`length`: it ran out of output tokens); and whether the run executed any tool between its
	 * `input` entry and the answer.
	 */
	async answerText(answer: EntryId, input: EntryId): Promise<RunAnswer> {
		const entry = await this.root.commit(
			async (tx) => tx.entry(AssistantEntry, answer),
			context,
		);
		const message = entry?.model?.[0];
		const usedTools = await this.ranTools(input, answer);
		if (message?.role !== "assistant") {
			return { text: "", toolCalls: false, stopReason: undefined, usedTools };
		}
		return {
			text: message.content
				.flatMap((block) => (block.type === "text" ? [block.text] : []))
				.join("")
				.trim(),
			toolCalls: message.content.some((block) => block.type === "toolCall"),
			stopReason: message.stopReason,
			usedTools,
		};
	}

	/** Whether a tool result was written between two entries. */
	private async ranTools(from: EntryId, to: EntryId): Promise<boolean> {
		let cursor: Parameters<Conversation["entries"]>[2];
		do {
			// oxlint-disable-next-line eslint/no-await-in-loop -- pages follow each other
			const page = await this.root.entries(
				{ minEntryId: from, maxEntryId: to, order: "descending" },
				500,
				cursor,
				context,
			);
			if (page.items.some((item) => item.kind === ToolResultEntry.kind)) {
				return true;
			}
			cursor = page.next;
		} while (cursor !== undefined);
		return false;
	}

	/** Results already posted (`answer-<entryId>`, `error-<submissionId>`), with their comment URLs. */
	async postedResults(): Promise<Map<string, string>> {
		const posted = new Map<string, string>();
		let cursor: Parameters<Conversation["entries"]>[2];
		do {
			// oxlint-disable-next-line eslint/no-await-in-loop -- pages follow each other
			const page = await this.root.entries(
				{ order: "ascending" },
				500,
				cursor,
				context,
			);
			for (const { kind, data } of page.items) {
				if (kind === POSTED_KIND && typeof data === "object" && data !== null) {
					const key: unknown = Reflect.get(data, KEY_FIELD);
					const url: unknown = Reflect.get(data, URL_FIELD);
					if (typeof key === "string") {
						posted.set(key, typeof url === "string" ? url : "");
					}
				}
			}
			cursor = page.next;
		} while (cursor !== undefined);
		return posted;
	}

	async markPosted(key: string, url: string): Promise<void> {
		await this.root.submit(
			{
				type: "write",
				entry: { kind: POSTED_KIND, data: { key, url } },
				requestId: `posted-${key}`,
			},
			context,
		);
	}

	async abort(): Promise<void> {
		await this.root.abort(context);
	}

	/** Push what is committed so far (with the working-tree snapshots); throws if the remote moved under us. */
	async push(): Promise<void> {
		await this.persistence?.saver.push("flush", false);
	}

	async close(): Promise<void> {
		if (this.closed) {
			return;
		}
		this.closed = true;
		const worktree = this.persistence?.worktree;
		await worktree?.checkpoint();
		// Turn boundaries the closing harness still commits must not save into a closed conversation.
		worktree?.detach();
		await this.harness.close(context);
		await this.push();
	}
}

/**
 * Configure the conversation for this run (the model, the tools may differ from the last run's): clear the last run's
 * tool filters, resolve the inputs against the tools there are now, and apply them. Returns the tools the model gets.
 */
async function configureAgent(
	root: Conversation,
	agent: AgentChange,
	options: ThreadOptions,
): Promise<string[]> {
	await root.configure({ ...agent, tools: null, modelTools: null }, context);
	const resolved = await root.agent(context);
	const byName = new Map<string, ToolRegistration>();
	for (const tool of [
		...resolved.tools,
		...resolved.callable,
		...resolved.deferred,
	]) {
		byName.set(tool.name, tool);
	}
	const offered = resolved.tools.map((tool) => tool.name);
	if (options.tools === undefined) {
		return offered;
	}
	const plan = planTools(
		options.tools,
		[...byName.keys()],
		offered,
		options.log,
	);
	const pick = (names: readonly string[]) =>
		names.flatMap((name) => byName.get(name) ?? []);
	if (plan.exclude.length > 0 || plan.hide.length > 0) {
		await root.configure(
			{
				...(plan.exclude.length > 0
					? { tools: { remove: pick(plan.exclude) } }
					: {}),
				...(plan.hide.length > 0
					? { modelTools: { remove: pick(plan.hide) } }
					: {}),
			},
			context,
		);
	}
	return plan.offered;
}

/**
 * Restore the working tree the conversation points at, before any work resumes, and tell the model how it went
 * (one entry with a user message).
 */
async function restoreWorktree(
	worktree: WorktreeContinuity | undefined,
	harness: Harness,
	root: Conversation,
): Promise<void> {
	if (worktree === undefined) {
		return;
	}
	worktree.attach(harness, root);
	const message = await worktree.restore();
	if (message !== undefined) {
		await root.submit(
			{
				type: "write",
				entry: {
					kind: RESTORE_ENTRY_KIND,
					data: { message },
					model: [{ role: "user", content: message, timestamp: Date.now() }],
				},
			},
			context,
		);
	}
}

/** When the thread's root commit was made. */
async function rootCommitTime(
	cwd: string,
	ref: string,
): Promise<Date | undefined> {
	const out = await git(cwd, [
		"log",
		"--max-parents=0",
		"--format=%cI",
		ref,
	]).catch(() => "");
	const [time] = out.trim().split("\n");
	return time ? new Date(time) : undefined;
}
",
  "src/durable-extensions.ts": "import { mkdir, mkdtemp } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join, resolve } from "node:path";

import type { Extension } from "@earendil-works/pi-durable";
import { CodingTools } from "@earendil-works/pi-durable/tools";

import type { DurableExtensionFactory } from "./extensions.ts";
import type { DurableUi, Log } from "./types.ts";
import { getErrorMessage } from "./utils.ts";

export interface DurableExtensionsOptions {
	/** The workspace (the checked-out repository). */
	cwd: string;
	/** The `agent_dir` input, relative to the workspace; a temp dir under RUNNER_TEMP when unset. */
	agentDir: string | undefined;
	/** The `trust_project` input. */
	trustProject: boolean;
	/** The GitHub UI, in comment mode on an issue or PR. */
	ui: DurableUi | undefined;
	log: Log;
	env: Record<string, string | undefined>;
}

/** The `agent_dir` input, or a fresh directory under RUNNER_TEMP. */
async function agentDirectory(
	options: DurableExtensionsOptions,
): Promise<string> {
	if (options.agentDir) {
		const dir = resolve(options.cwd, options.agentDir);
		await mkdir(dir, { recursive: true });
		return dir;
	}
	const base = options.env["RUNNER_TEMP"] || tmpdir();
	await mkdir(base, { recursive: true });
	return mkdtemp(join(base, "pi-action-agent-"));
}

/**
 * Builds the pi-durable extensions the `extensions` input declared, with the run's host options, for the thread's
 * registry. Their names must not collide with each other or with pi-action's coding tools. Their tools may: a tool
 * named like an earlier one replaces it (the last one wins, as with pi's `registerTool`), which the log says.
 */
export async function createDurableExtensions(
	factories: readonly DurableExtensionFactory[],
	options: DurableExtensionsOptions,
): Promise<Extension[]> {
	if (factories.length === 0) {
		return [];
	}
	const { cwd, trustProject, ui, log } = options;
	const agentDir = await agentDirectory(options);
	log.info(
		`pi-durable extensions: agent directory ${agentDir}, project ${trustProject ? "trusted" : "not trusted"}, ${ui ? "questions answered on GitHub" : "no UI"}`,
	);
	const names = new Set([CodingTools.name]);
	const owners = new Map(
		(CodingTools.tools ?? []).map((tool) => [tool.name, CodingTools.name]),
	);
	const extensions: Extension[] = [];
	for (const factory of factories) {
		let extension: Extension;
		try {
			// oxlint-disable-next-line eslint/no-await-in-loop -- extensions are created in order, as they were loaded
			extension = await factory.create({
				cwd,
				agentDir,
				trustProject,
				...(ui ? { ui } : {}),
				log: { info: log.info, warning: log.warning },
			});
		} catch (error) {
			throw new Error(
				`Could not create pi-durable extension ${factory.source}: ${getErrorMessage(error)}`,
				{ cause: error },
			);
		}
		if (names.has(extension.name)) {
			throw new Error(
				`pi-durable extension ${factory.source} is named "${extension.name}", which is already taken`,
			);
		}
		names.add(extension.name);
		for (const { name } of extension.tools ?? []) {
			const owner = owners.get(name);
			if (owner !== undefined && owner !== extension.name) {
				log.info(
					`pi-durable extension ${extension.name} replaces tool ${name} from ${owner}`,
				);
			}
			owners.set(name, extension.name);
		}
		log.info(
			`pi-durable extension ${extension.name} (${factory.source}): ${(extension.tools ?? []).map((tool) => tool.name).join(", ") || "no tools"}`,
		);
		extensions.push(extension);
	}
	return extensions;
}
",
  "src/inputs.ts": "// Reading the action's inputs (see action.yml) into ActionInputs. Empty or invalid values fall back to DEFAULTS.
import type {
	CustomProviderConfig,
	ModelInputMode,
} from "./custom-provider.ts";
import { DEFAULTS } from "./defaults.ts";
import {
	DEFAULT_SNAPSHOT_LIMITS,
	type SnapshotLimits,
} from "./storage/worktree.ts";

export type InputReader = (name: string) => string;

export interface ActionInputs {
	triggerPhrase: string;
	allowedBots: string[];
	allowedUsers: string[];
	allowedAssociations: string[];
	provider: string;
	model: string;
	/** Seconds before the run is aborted. */
	timeout: number;
	githubToken: string | undefined;
	/** The provider's key, kept in memory for this run only. */
	apiKey: string | undefined;
	customProvider: CustomProviderConfig | undefined;
	promptTemplate: string | undefined;
	outputMode: "comment" | "output";
	prompt: string | undefined;
	prNumber: number | undefined;
	/** Seconds between checks for new comments while pi works. */
	pollInterval: number;
	/** pi extensions to load (npm specs or workspace paths) for the providers they register. */
	extensions: string[];
	/** Whether pi-durable extensions may load and run the repository's own configuration (`trust_project`). */
	trustProject: boolean;
	/** The agent directory for pi-durable extensions; a temp dir when unset. */
	agentDir: string | undefined;
	/** Whether a thread saves and restores the files pi left uncommitted (`worktree_snapshots`). */
	worktreeSnapshots: boolean;
	/** What a snapshot leaves out of the untracked files. */
	worktreeLimits: SnapshotLimits;
	/** `exclude_tools`: tool name globs to disable completely. */
	excludeTools: string[];
	/** `model_tools_hidden`: tool name globs the model is not offered (other tools can still call them). */
	modelToolsHidden: string[];
}

const TRUE_VALUES = new Set(["true", "1", "yes", "y", "on"]);
const FALSE_VALUES = new Set(["false", "0", "no", "n", "off"]);
const MODEL_INPUT_MODES: ReadonlySet<string> = new Set<ModelInputMode>([
	"text",
	"image",
]);
const INTEGER_PATTERN = /^\d+$/u;
const LINE_BREAK = /\r?\n/u;
/** A `#` at the start of a line or after whitespace starts a comment; `github:owner/repo#ref` keeps its `#`. */
const EXTENSION_COMMENT = /(?:^|\s)#.*$/u;
const COMPAT_INPUTS = {
	supportsDeveloperRole: "compat_supports_developer_role",
	supportsReasoningEffort: "compat_supports_reasoning_effort",
	forceAdaptiveThinking: "compat_force_adaptive_thinking",
} as const;

export function parseCsv(value: string): string[] {
	return value
		.split(",")
		.map((entry) => entry.trim())
		.filter(Boolean);
}

/**
 * pi extension specs, newline- or comma-separated. Blank lines are skipped, and so are `#` comments: whole lines, or
 * the rest of a line after a spec (`pkg@1.2.3  # why`). Comments are removed before the commas split the line.
 */
export function parseExtensionSpecs(value: string): string[] {
	return value
		.split(LINE_BREAK)
		.flatMap((line) => line.replace(EXTENSION_COMMENT, "").split(","))
		.map((spec) => spec.trim())
		.filter((spec) => spec !== "" && !spec.startsWith("#"));
}

/** true/1/yes/y/on or false/0/no/n/off, in any case; undefined for anything else. */
export function parseBoolean(value: string): boolean | undefined {
	const normalized = value.trim().toLowerCase();
	if (TRUE_VALUES.has(normalized)) {
		return true;
	}
	return FALSE_VALUES.has(normalized) ? false : undefined;
}

export function parsePositiveInteger(value: string): number | undefined {
	const normalized = value.trim();
	const parsed = INTEGER_PATTERN.test(normalized)
		? Number.parseInt(normalized, 10)
		: 0;
	return parsed > 0 ? parsed : undefined;
}

function parseModelInputModes(value: string): ModelInputMode[] {
	const modes = parseCsv(value).filter((mode): mode is ModelInputMode =>
		MODEL_INPUT_MODES.has(mode),
	);
	return modes.length > 0 ? modes : [DEFAULTS.customModelInput];
}

function readCompat(readInput: InputReader): CustomProviderConfig["compat"] {
	const compat = Object.fromEntries(
		Object.entries(COMPAT_INPUTS).flatMap(([key, name]) => {
			const value = parseBoolean(readInput(name));
			return value === undefined ? [] : [[key, value]];
		}),
	);
	return Object.keys(compat).length > 0 ? compat : undefined;
}

/** The single custom provider/model from the flat provider_* and model_* inputs; undefined without a base URL. */
export function readCustomProviderConfig(
	readInput: InputReader,
): CustomProviderConfig | undefined {
	const baseUrl = readInput("provider_base_url").trim();
	if (!baseUrl) {
		return undefined;
	}
	const apiKey = readInput("provider_api_key").trim();
	const modelName = readInput("model_name").trim();
	const compat = readCompat(readInput);
	return {
		baseUrl,
		api: readInput("provider_api") || DEFAULTS.customProviderApi,
		...(apiKey ? { apiKey } : {}),
		authHeader:
			parseBoolean(readInput("provider_auth_header")) ??
			DEFAULTS.customProviderAuthHeader,
		...(modelName ? { modelName } : {}),
		reasoning:
			parseBoolean(readInput("model_reasoning")) ??
			DEFAULTS.customModelReasoning,
		input: parseModelInputModes(readInput("model_input")),
		contextWindow:
			parsePositiveInteger(readInput("model_context_window")) ??
			DEFAULTS.customModelContextWindow,
		maxTokens:
			parsePositiveInteger(readInput("model_max_tokens")) ??
			DEFAULTS.customModelMaxTokens,
		...(compat ? { compat } : {}),
	};
}

export function readActionInputs(
	readInput: InputReader,
	env: Record<string, string | undefined> = process.env,
): ActionInputs {
	return {
		triggerPhrase: readInput("trigger_phrase") || DEFAULTS.triggerPhrase,
		allowedBots: parseCsv(readInput("allowed_bots")),
		allowedUsers: parseCsv(readInput("allowed_users")),
		allowedAssociations: parseCsv(
			readInput("allowed_associations") ||
				DEFAULTS.allowedAssociations.join(","),
		),
		provider: readInput("provider") || DEFAULTS.provider,
		model: readInput("model") || DEFAULTS.model,
		timeout: parsePositiveInteger(readInput("timeout")) ?? DEFAULTS.timeout,
		githubToken: readInput("github_token") || env["GITHUB_TOKEN"],
		apiKey: readInput("api_key") || undefined,
		customProvider: readCustomProviderConfig(readInput),
		promptTemplate: readInput("prompt_template") || undefined,
		outputMode:
			readInput("output_mode") === "output" ? "output" : DEFAULTS.outputMode,
		prompt: readInput("prompt") || undefined,
		prNumber: parsePositiveInteger(readInput("pr_number")),
		pollInterval:
			parsePositiveInteger(readInput("poll_interval")) ?? DEFAULTS.pollInterval,
		extensions: parseExtensionSpecs(readInput("extensions")),
		trustProject:
			parseBoolean(readInput("trust_project")) ?? DEFAULTS.trustProject,
		agentDir: readInput("agent_dir").trim() || undefined,
		worktreeSnapshots:
			parseBoolean(readInput("worktree_snapshots")) ??
			DEFAULTS.worktreeSnapshots,
		worktreeLimits: {
			...DEFAULT_SNAPSHOT_LIMITS,
			exclude: parseExtensionSpecs(readInput("worktree_snapshot_exclude")),
		},
		excludeTools: parseExtensionSpecs(readInput("exclude_tools")),
		modelToolsHidden: parseExtensionSpecs(readInput("model_tools_hidden")),
	};
}
